216 | // isMemoShareExpired returns true if the share has a defined expiry that has already passed.
217 | func isMemoShareExpired(ms *store.MemoShare) bool {
218 | 	return ms.ExpiresTs != nil && time.Now().Unix() > *ms.ExpiresTs
219 | }
